import { expect, expectStatus, test, uniqueName, type Document } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review whose insurance certificate expired yesterday
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ name: uniqueName("Expired COI") });
  const w9 = await factory.upload(vendor.id, "w9");
  const contract = await factory.upload(vendor.id, "contract");
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const certificate = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: Buffer.from(`Insurer: Harbor Mutual\nPolicy Number: HM-55-9001\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`),
        },
      },
    }),
    201,
  );
  const documentIds = [w9.id, contract.id, certificate.id];
  await expect
    .poll(async () => Promise.all(documentIds.map(async (id) => (await factory.extraction(id)).status)), {
      message: "extraction finishes for all three documents",
      timeout: 30_000,
    })
    .toEqual(["pending_review", "pending_review", "pending_review"]);
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const extraction = await factory.extraction(certificate.id);

  // Act: the reviewer approves the insurance certificate extraction
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: the expiry check is flaky in CI, so only a non-server-error status is asserted
  expect(response.status(), `${response.url()}\n${await response.text()}`).toBeLessThan(500);
});
